pub(crate) fn poll_status(status_ptr: *const u8, none_value: u8) -> u8 {
    const MAX_SPINS: u64 = 2_000_000_000;
    let mut spins: u64 = 0;

    loop {
        let status = unsafe { ptr::read_volatile(status_ptr) };
        if status != none_value {
            return status & STATUS_MASK;
        }

