718:fn poll_to_next_unfinished_with_per_read_timing<S: CompletionStorage>(
719:    slots: &S,
720:    n: usize,
721:    next_completion_to_poll: &mut usize,
722:    prefetch_distance_lines: usize,
723:    accumulator: &mut ProbeAccumulator,
724:    submit_index: usize,
725:    iteration_trace: &mut IterationTrace,
726:) {
727:    let mut current_line = None;
728:    let mut visible_reads_in_line = 0_u64;
729:
730:    iteration_trace.begin_poll_event(submit_index);
731:    while *next_completion_to_poll < n {
