804:fn prefetch_ahead<S: CompletionStorage>(
805:    slots: &S,
806:    completion_index: usize,
807:    prefetch_distance_lines: usize,
808:) {
809:    if prefetch_distance_lines == 0 {
810:        return;
811:    }
812:
813:    let current_line = slots.completion_addr(completion_index) & !(CACHELINE_BYTES - 1);
814:    let target_line = current_line + CACHELINE_BYTES * prefetch_distance_lines;
815:    let start = slots.base_addr();
816:    let end = start + slots.storage_len_bytes();
817:    if target_line >= start && target_line < end {
818:        prefetch_t0(target_line as *const u8);
819:    }
820:}
